-- ═══ Part B: security ═══

-- ─── 1. Domain integrity Prisma cannot express ───────────────────────────────────────────────────────────────
ALTER TABLE "identity"."local_accounts" ADD CONSTRAINT local_accounts_status_chk CHECK (status IN ('active', 'disabled'));
ALTER TABLE "identity"."local_account_tokens" ADD CONSTRAINT local_account_tokens_purpose_chk CHECK (purpose IN ('verify_email', 'reset_password'));
ALTER TABLE "users" ADD CONSTRAINT users_status_chk CHECK (status IN ('active', 'deactivated'));
ALTER TABLE "organizations" ADD CONSTRAINT organizations_status_chk CHECK (status IN ('active', 'suspended', 'deleted'));
ALTER TABLE "workspaces" ADD CONSTRAINT workspaces_status_chk CHECK (status IN ('active', 'archived'));
ALTER TABLE "roles" ADD CONSTRAINT roles_scope_chk CHECK (scope IN ('organization', 'workspace'));
ALTER TABLE "roles" ADD CONSTRAINT roles_system_key_chk CHECK ((is_system AND key IS NOT NULL) OR (NOT is_system AND key IS NULL));
ALTER TABLE "organization_memberships" ADD CONSTRAINT org_memberships_status_chk CHECK (status IN ('active', 'suspended', 'removed'));
ALTER TABLE "invitations" ADD CONSTRAINT invitations_status_chk CHECK (status IN ('pending', 'accepted', 'revoked', 'expired'));
ALTER TABLE "audit_logs" ADD CONSTRAINT audit_logs_outcome_chk CHECK (outcome IN ('success', 'denied', 'failure'));
ALTER TABLE "audit_logs" ADD CONSTRAINT audit_logs_actor_type_chk CHECK (actor_type IN ('user', 'api_key', 'system'));

-- ─── 2. Schemas and tenant-context functions ─────────────────────────────────────────────────────────────────
CREATE SCHEMA IF NOT EXISTS app;
REVOKE ALL ON SCHEMA app FROM PUBLIC;
REVOKE ALL ON SCHEMA identity FROM PUBLIC;
REVOKE ALL ON SCHEMA public FROM PUBLIC;

GRANT USAGE ON SCHEMA public TO workeasy_app, workeasy_reporting;
GRANT USAGE ON SCHEMA app TO workeasy_app, workeasy_reporting;
GRANT USAGE ON SCHEMA identity TO workeasy_identity;

-- Context is set per transaction by @workeasy/db (set_config(..., true)). Missing/empty context → NULL → policies
-- match nothing, so forgetting the context returns zero rows instead of leaking.
CREATE FUNCTION app.current_org_id() RETURNS uuid LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.org_id', true), '')::uuid $$;
CREATE FUNCTION app.current_workspace_id() RETURNS uuid LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.workspace_id', true), '')::uuid $$;
CREATE FUNCTION app.current_user_id() RETURNS uuid LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;

REVOKE ALL ON FUNCTION app.current_org_id(), app.current_workspace_id(), app.current_user_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.current_org_id(), app.current_workspace_id(), app.current_user_id()
  TO workeasy_app, workeasy_reporting;

-- ─── 3. Append-only guard (defence in depth on top of grants; also stops accidental owner UPDATEs) ──────────
CREATE FUNCTION app.reject_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE TRIGGER audit_logs_append_only BEFORE UPDATE ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION app.reject_update();
CREATE TRIGGER domain_events_append_only BEFORE UPDATE ON "domain_events" FOR EACH ROW EXECUTE FUNCTION app.reject_update();
CREATE TRIGGER security_events_append_only BEFORE UPDATE ON "security_events" FOR EACH ROW EXECUTE FUNCTION app.reject_update();
CREATE TRIGGER login_attempts_append_only BEFORE UPDATE ON "identity"."login_attempts" FOR EACH ROW EXECUTE FUNCTION app.reject_update();

-- ─── 4. Privileges: workeasy_identity (local IdP) — identity schema only ────────────────────────────────────
GRANT SELECT, INSERT ON "identity"."local_accounts" TO workeasy_identity;
GRANT UPDATE (email, email_verified_at, status, failed_login_count, locked_until, password_hash, password_changed_at, updated_at)
  ON "identity"."local_accounts" TO workeasy_identity;
GRANT SELECT, INSERT ON "identity"."local_account_tokens" TO workeasy_identity;
GRANT UPDATE (consumed_at) ON "identity"."local_account_tokens" TO workeasy_identity;
GRANT SELECT, INSERT ON "identity"."login_attempts" TO workeasy_identity;

-- ─── 5. Privileges: workeasy_app (runtime) — column-level UPDATE; ids and tenant keys are never updatable ─────
GRANT SELECT ON "users" TO workeasy_app;
GRANT UPDATE (display_name, last_login_at, updated_at, version) ON "users" TO workeasy_app;

GRANT SELECT ON "user_identities" TO workeasy_app;
GRANT UPDATE (last_used_at) ON "user_identities" TO workeasy_app;

GRANT SELECT, INSERT ON "sessions" TO workeasy_app;
GRANT UPDATE (token_hash, previous_token_hash, previous_token_valid_until, last_seen_at, rotated_at, idle_expires_at,
              revoked_at, revoked_reason, ip_address, user_agent, last_organization_id, last_workspace_id)
  ON "sessions" TO workeasy_app;

GRANT SELECT ON "security_events" TO workeasy_app;           -- inserts only via app.record_security_event()
GRANT SELECT, INSERT, DELETE ON "idempotency_records" TO workeasy_app;

GRANT SELECT, INSERT ON "organizations" TO workeasy_app;
GRANT UPDATE (name, status, updated_at, deleted_at, version) ON "organizations" TO workeasy_app;

GRANT SELECT, INSERT ON "workspaces" TO workeasy_app;
GRANT UPDATE (name, slug, timezone, status, updated_at, archived_at, version) ON "workspaces" TO workeasy_app;

GRANT SELECT, INSERT ON "workspace_settings" TO workeasy_app;
GRANT UPDATE (default_sender_name, default_reply_to, locale, updated_at, version) ON "workspace_settings" TO workeasy_app;

GRANT SELECT, INSERT ON "roles" TO workeasy_app;
GRANT UPDATE (name, description, permissions, updated_at, deleted_at, version) ON "roles" TO workeasy_app;

GRANT SELECT, INSERT ON "organization_memberships" TO workeasy_app;
GRANT UPDATE (role_id, status, updated_at, suspended_at, removed_at, version) ON "organization_memberships" TO workeasy_app;

GRANT SELECT, INSERT, DELETE ON "workspace_memberships" TO workeasy_app;
GRANT UPDATE (role_id, updated_at, version) ON "workspace_memberships" TO workeasy_app;

GRANT SELECT, INSERT ON "invitations" TO workeasy_app;
GRANT UPDATE (status, token_hash, expires_at, accepted_at, accepted_by_user_id, revoked_at, version) ON "invitations" TO workeasy_app;

GRANT SELECT, INSERT ON "audit_logs" TO workeasy_app;        -- append-only
GRANT SELECT, INSERT ON "domain_events" TO workeasy_app;     -- append-only
GRANT SELECT, INSERT ON "provider_message_routes" TO workeasy_app;

-- ─── 6. Privileges: workeasy_reporting — read-only, still tenant-scoped by RLS ─────────────────────────────
GRANT SELECT ON "organizations", "workspaces", "audit_logs", "domain_events" TO workeasy_reporting;

-- ─── 7. Row-level security: ENABLE + FORCE on every public table ────────────────────────────────────────────
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['users', 'user_identities', 'sessions', 'security_events', 'idempotency_records',
                           'organizations', 'workspaces', 'workspace_settings', 'roles', 'organization_memberships',
                           'workspace_memberships', 'invitations', 'audit_logs', 'domain_events',
                           'provider_message_routes']
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;

-- user-owned
CREATE POLICY users_select ON "users" FOR SELECT USING (
  id = app.current_user_id()
  OR EXISTS (SELECT 1 FROM organization_memberships m
             WHERE m.user_id = users.id AND m.org_id = app.current_org_id() AND m.status <> 'removed'));
CREATE POLICY users_update ON "users" FOR UPDATE
  USING (id = app.current_user_id()) WITH CHECK (id = app.current_user_id());

CREATE POLICY user_identities_own ON "user_identities" FOR ALL
  USING (user_id = app.current_user_id()) WITH CHECK (user_id = app.current_user_id());
CREATE POLICY sessions_own ON "sessions" FOR ALL
  USING (user_id = app.current_user_id()) WITH CHECK (user_id = app.current_user_id());
CREATE POLICY security_events_own ON "security_events" FOR SELECT USING (user_id = app.current_user_id());
CREATE POLICY idempotency_own ON "idempotency_records" FOR ALL
  USING (user_id = app.current_user_id()) WITH CHECK (user_id = app.current_user_id());

-- organization-owned
CREATE POLICY organizations_select ON "organizations" FOR SELECT USING (
  id = app.current_org_id()
  OR EXISTS (SELECT 1 FROM organization_memberships m
             WHERE m.org_id = organizations.id AND m.user_id = app.current_user_id() AND m.status = 'active'));
CREATE POLICY organizations_insert ON "organizations" FOR INSERT
  WITH CHECK (id = app.current_org_id() AND created_by_user_id = app.current_user_id());
CREATE POLICY organizations_update ON "organizations" FOR UPDATE
  USING (id = app.current_org_id()) WITH CHECK (id = app.current_org_id());

CREATE POLICY roles_select ON "roles" FOR SELECT USING (
  org_id = app.current_org_id()
  OR EXISTS (SELECT 1 FROM organization_memberships m
             WHERE m.role_id = roles.id AND m.user_id = app.current_user_id() AND m.status = 'active'));
CREATE POLICY roles_write ON "roles" FOR INSERT WITH CHECK (org_id = app.current_org_id());
CREATE POLICY roles_update ON "roles" FOR UPDATE
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());

CREATE POLICY org_memberships_select ON "organization_memberships" FOR SELECT
  USING (org_id = app.current_org_id() OR user_id = app.current_user_id());
CREATE POLICY org_memberships_insert ON "organization_memberships" FOR INSERT WITH CHECK (org_id = app.current_org_id());
CREATE POLICY org_memberships_update ON "organization_memberships" FOR UPDATE
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());

CREATE POLICY ws_memberships_select ON "workspace_memberships" FOR SELECT
  USING (org_id = app.current_org_id() OR user_id = app.current_user_id());
CREATE POLICY ws_memberships_insert ON "workspace_memberships" FOR INSERT WITH CHECK (org_id = app.current_org_id());
CREATE POLICY ws_memberships_update ON "workspace_memberships" FOR UPDATE
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());
CREATE POLICY ws_memberships_delete ON "workspace_memberships" FOR DELETE USING (org_id = app.current_org_id());

CREATE POLICY workspaces_tenant ON "workspaces" FOR ALL
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());
CREATE POLICY invitations_tenant ON "invitations" FOR ALL
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());
CREATE POLICY audit_logs_tenant ON "audit_logs" FOR ALL
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());
CREATE POLICY domain_events_tenant ON "domain_events" FOR ALL
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());
CREATE POLICY provider_routes_tenant ON "provider_message_routes" FOR ALL
  USING (org_id = app.current_org_id()) WITH CHECK (org_id = app.current_org_id());

-- workspace-owned: both keys must match the context
CREATE POLICY workspace_settings_tenant ON "workspace_settings" FOR ALL
  USING (org_id = app.current_org_id() AND workspace_id = app.current_workspace_id())
  WITH CHECK (org_id = app.current_org_id() AND workspace_id = app.current_workspace_id());

-- ─── 8. SECURITY DEFINER discovery functions (owner bypasses RLS; each returns the minimum) ─────────────────
-- Rules: fixed search_path; no dynamic SQL; return ids/status only; EXECUTE granted to workeasy_app only.

-- Map an authenticated external identity to a platform user, creating the user on first sight.
-- Never links by email alone: an existing user with the same email but a different identity is an error,
-- so a new identity provider cannot take over an account (docs/identity.md §Account linking).
CREATE FUNCTION app.link_identity(p_provider text, p_subject text, p_email text, p_display_name text,
                                  p_email_verified boolean)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE v_user uuid;
BEGIN
  SELECT user_id INTO v_user FROM user_identities WHERE provider = p_provider AND subject = p_subject;
  IF v_user IS NOT NULL THEN
    UPDATE user_identities SET last_used_at = now() WHERE provider = p_provider AND subject = p_subject;
    IF p_email_verified THEN
      UPDATE users SET email_verified_at = coalesce(email_verified_at, now()) WHERE id = v_user;
    END IF;
    RETURN v_user;
  END IF;
  IF EXISTS (SELECT 1 FROM users WHERE email_normalized = lower(p_email)) THEN
    RAISE EXCEPTION 'email already belongs to another identity' USING ERRCODE = 'unique_violation';
  END IF;
  v_user := gen_random_uuid();
  INSERT INTO users (id, email, email_normalized, display_name, email_verified_at)
    VALUES (v_user, p_email, lower(p_email), p_display_name, CASE WHEN p_email_verified THEN now() END);
  INSERT INTO user_identities (id, user_id, provider, subject, last_used_at)
    VALUES (gen_random_uuid(), v_user, p_provider, p_subject, now());
  RETURN v_user;
END $$;

-- Session lookup by token hash, before any user context exists. Returns the session only if the token is
-- current, or is the previous token within its rotation grace window.
CREATE FUNCTION app.resolve_session(p_token_hash text)
RETURNS TABLE (session_id uuid, user_id uuid, user_status text, provider text, auth_methods text[],
               created_at timestamptz, rotated_at timestamptz, idle_expires_at timestamptz,
               absolute_expires_at timestamptz, revoked_at timestamptz, is_previous_token boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT s.id, s.user_id, u.status, s.provider, s.auth_methods, s.created_at, s.rotated_at, s.idle_expires_at,
         s.absolute_expires_at, s.revoked_at, (s.token_hash <> p_token_hash)
  FROM sessions s JOIN users u ON u.id = s.user_id
  WHERE s.token_hash = p_token_hash
     OR (s.previous_token_hash = p_token_hash AND s.previous_token_valid_until > now())
$$;

-- Invitation lookup by token hash (the invitee has no org context yet).
CREATE FUNCTION app.find_invitation(p_token_hash text)
RETURNS TABLE (id uuid, org_id uuid, org_name text, email text, email_normalized text, status text,
               expires_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT i.id, i.org_id, o.name, i.email, i.email_normalized, i.status, i.expires_at
  FROM invitations i JOIN organizations o ON o.id = i.org_id
  WHERE i.token_hash = p_token_hash AND o.status = 'active'
$$;

-- Inbound provider callbacks: tenant comes from our routing table, never from the payload.
CREATE FUNCTION app.resolve_provider_message(p_provider text, p_provider_message_id text)
RETURNS TABLE (org_id uuid, workspace_id uuid, delivery_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT r.org_id, r.workspace_id, r.delivery_id FROM provider_message_routes r
  WHERE r.provider = p_provider AND r.provider_message_id = p_provider_message_id
$$;

-- Slug availability across all organizations (RLS hides other orgs from the caller).
CREATE FUNCTION app.organization_slug_taken(p_slug text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  SELECT EXISTS (SELECT 1 FROM organizations WHERE slug = p_slug)
$$;

-- Security events may concern a user who is not (yet) the session principal, e.g. a failed login.
CREATE FUNCTION app.record_security_event(p_user_id uuid, p_type text, p_ip text, p_user_agent text,
                                          p_correlation_id uuid, p_metadata jsonb)
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
  INSERT INTO security_events (id, user_id, type, ip_address, user_agent, correlation_id, metadata)
  VALUES (gen_random_uuid(), p_user_id, p_type, p_ip, p_user_agent, p_correlation_id, coalesce(p_metadata, '{}'))
$$;

REVOKE ALL ON FUNCTION app.link_identity(text, text, text, text, boolean), app.resolve_session(text),
  app.find_invitation(text), app.resolve_provider_message(text, text), app.organization_slug_taken(text),
  app.record_security_event(uuid, text, text, text, uuid, jsonb), app.reject_update() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.link_identity(text, text, text, text, boolean), app.resolve_session(text),
  app.find_invitation(text), app.resolve_provider_message(text, text), app.organization_slug_taken(text),
  app.record_security_event(uuid, text, text, text, uuid, jsonb) TO workeasy_app;
